(function executeRule(current, previous /*null when async*/) {
    var bookStart = new GlideDateTime(current.start_date);
    var bookEnd = new GlideDateTime(current.end_date);

    var gr = new GlideRecord('x_1809800_event_0_room_maintenance');
    gr.addQuery('room', current.room);
    gr.addQuery('start_dateTime', '<=', bookEnd);
    gr.addQuery('end_dateTime', '>=', bookStart);
    gr.query();

    if (gr.hasNext()) {
        gs.addErrorMessage("Sorry, this room can't be allocated since it is under maintenance.");
        current.setAbortAction(true);
    }
})(current, previous);
